// HasMessagesOutboundID applies the HasEdge predicate on the "messages_outbound_id" edge.
func HasMessagesOutboundID() predicate.AgentOutboundMessage {
	return predicate.AgentOutboundMessage(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, MessagesOutboundIDTable, MessagesOutboundIDColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasMessagesOutboundIDWith applies the HasEdge predicate on the "messages_outbound_id" edge with a given conditions (other predicates).
func HasMessagesOutboundIDWith(preds ...predicate.Message) predicate.AgentOutboundMessage {
	return predicate.AgentOutboundMessage(func(s *sql.Selector) {
		step := newMessagesOutboundIDStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

